use cyclecare_core::{local_plan_wire::plan,sync_codec as c};
use serde_json::{Value,json};
fn request()->Value{json!(["local-plan-wire-v1",["cycle_care_database","dev","db",1,2,3,true],"op","SAVE","+10000-01-01",7,9,[["+10000-01-01","HEAVY","","","","","","","NONE",2147483648u32,0,"",i32::MIN,"x",i32::MAX],[1,true,"goals","",28,5,14,true,5,true,false,"",true,true,true]]])}
#[test]fn raw_bits_full_range_anchor_and_canonical(){let r:Value=serde_json::from_str(&plan(&request().to_string()).unwrap()).unwrap();assert_eq!(r[0],"local-plan-result-v1");assert_eq!(r[2],c::sha256_hex(r[1].as_str().unwrap()));assert_eq!(r[4].as_array().unwrap().len(),2);assert_eq!(r[4][0][4],2147483648u32);let p:Value=serde_json::from_str(r[4][0][2].as_str().unwrap()).unwrap();assert_eq!(p["water_glasses"],i32::MIN);assert_eq!(p["pain_intensity"],i32::MAX);assert!(r[4][0][2].as_str().unwrap().contains("\"bbt_celsius\":-0"));}
#[test]fn strict_types_and_nonfinite_reject(){for index in [0,1,2,3,4,5,6,7]{let mut r=request();r[index]=Value::Null;assert!(plan(&r.to_string()).is_err(),"{index}")};let mut r=request();r[7][0][9]=json!(2139095040u32);assert_eq!(plan(&r.to_string()),Err("NonFinite".into()));r=request();r[7][0][9]=json!(-1);assert!(plan(&r.to_string()).is_err());r=request();r[7][0][0]=json!("2024-01-01");assert!(plan(&r.to_string()).is_err());r=request();r[7][1][0]=json!(2);assert!(plan(&r.to_string()).is_err());}
#[test]fn delete_is_pure_explicit_and_versioned(){let mut r=request();r[3]=json!("DELETE");r[7]=Value::Null;let out:Value=serde_json::from_str(&plan(&r.to_string()).unwrap()).unwrap();assert!(out[3].as_array().unwrap().is_empty());assert!(out[4][0][2].is_null());r[0]=json!("v0");assert!(plan(&r.to_string()).is_err());}
